/* Otter2 Guide — Bé Rái Cá dẫn đường (stage 1, additive module).
   Self-contained: injects its own CSS + DOM, uses only guide-prefixed
   ids/classes, never touches existing page elements except clicking the
   site's own nav buttons to switch screens; the arrival highlight is a
   fixed-position overlay in the guide's own root, not a style on the
   destination element.
   Voice note: assets/index2/otter2-voice.js exposes only a settings UI
   (window.otter2OpenVoiceSettings / createVoiceSettings) — no reusable
   speak() function — and the inline engines keep their say() inside IIFEs
   (not on window, hard-coded zh-CN). So the guide speaks Vietnamese via
   window.speechSynthesis with a vi-VN voice, per the approved preview. */
(function () {
  "use strict";
  if (window.__OTTER2_GUIDE__) return;
  window.__OTTER2_GUIDE__ = true;

  var IMG_SRC = "data:image/webp;base64,";

  function init() {
    try {
      build();
    } catch (e) {
      /* The guide must never break the page. */
      if (window.console && console.warn) console.warn("Otter guide disabled:", e);
    }
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  function build() {
    var reducedMotion = !!(
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    );

    /* ---------------- CSS (injected, guide-prefixed) ---------------- */
    var css = [
      ".guide-roam{position:fixed;left:0;top:0;z-index:90;width:118px;pointer-events:none;will-change:transform;transition:opacity .25s ease}",
      "@media (max-width:720px){.guide-roam{width:69px}}",
      ".guide-roam.guide-scrolling{opacity:.45}",
      ".guide-roam.guide-scrolling .guide-otter{scale:.85}",
      "@media (max-width:720px){.guide-roam.guide-scrolling .guide-otter{scale:.8}}",
      ".guide-roam[hidden]{display:none}",
      ".guide-otter{position:relative;display:block;width:100%;border:0;background:transparent;padding:0;pointer-events:auto;cursor:pointer;min-height:0;-webkit-tap-highlight-color:transparent;transition:scale .25s ease;transform-origin:50% 100%}",
      "@media (max-width:720px){.guide-otter{scale:1}}",
      ".guide-otter .guide-body{display:block;position:relative;transform-origin:50% 92%;animation:guideOtterIdle 2.6s ease-in-out infinite}",
      ".guide-otter.guide-face-left .guide-body{scale:-1 1}",
      ".guide-otter img{width:100%;height:auto;display:block;filter:drop-shadow(0 5px 8px rgba(25,25,33,.28))}",
      ".guide-otter-shadow{position:absolute;left:15%;right:15%;bottom:-5px;height:12px;border-radius:50%;background:rgba(25,25,33,.20);filter:blur(3px);pointer-events:none}",
      ".guide-otter .guide-badge{position:absolute;top:2px;right:6px;min-width:25px;height:25px;padding:0 6px;border-radius:999px;background:#d63a2f;color:#fff;font-size:.8rem;font-weight:800;display:grid;place-items:center;border:2px solid #fff;z-index:2}",
      ".guide-roam.guide-is-running .guide-body{animation:guideOtterRun .26s ease-in-out infinite}",
      ".guide-roam.guide-is-jumping .guide-body{animation:guideOtterJump .62s ease}",
      "@keyframes guideOtterIdle{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-4px) rotate(-1.2deg)}}",
      "@keyframes guideOtterRun{0%,100%{transform:translateY(0) rotate(-3.5deg)}50%{transform:translateY(-10px) rotate(3.5deg)}}",
      "@keyframes guideOtterJump{0%{transform:translateY(0)}35%{transform:translateY(-30px) rotate(-4deg)}70%{transform:translateY(0)}85%{transform:translateY(-9px)}100%{transform:translateY(0)}}",
      ".guide-dust{position:absolute;bottom:0;left:8px;width:10px;height:10px;border-radius:50%;background:#8a877e;opacity:0;pointer-events:none}",
      ".guide-dust.guide-d2{left:26px}.guide-dust.guide-d3{left:44px}",
      ".guide-roam.guide-is-running .guide-dust{animation:guideDustPuff .38s linear infinite}",
      ".guide-roam.guide-is-running .guide-dust.guide-d2{animation-delay:.13s}",
      ".guide-roam.guide-is-running .guide-dust.guide-d3{animation-delay:.25s}",
      "@keyframes guideDustPuff{0%{opacity:.45;transform:translate(0,0) scale(.6)}100%{opacity:0;transform:translate(-18px,-14px) scale(1.6)}}",
      ".guide-bubble{position:absolute;bottom:calc(100% + 12px);right:-4px;width:238px;max-width:78vw;background:#fff;border:1px solid #e3e0d8;border-radius:16px 16px 4px 16px;box-shadow:0 14px 40px rgba(25,25,33,.22);padding:11px 32px 11px 13px;pointer-events:auto;color:#23222b}",
      ".guide-bubble[hidden]{display:none}",
      ".guide-roam.guide-bubble-left .guide-bubble{border-radius:16px 16px 16px 4px}",
      ".guide-bubble p{margin:0;font-size:.84rem;font-weight:600;line-height:1.5}",
      ".guide-bubble .guide-hint{display:block;margin-top:5px;font-size:.72rem;font-weight:700;color:#d63a2f}",
      ".guide-bubble-x{position:absolute;top:2px;right:4px;border:0;background:transparent;color:#8a877e;font-size:.95rem;line-height:1;min-height:2rem;width:2rem;padding:0;cursor:pointer}",
      ".guide-wrap{position:fixed;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:95;pointer-events:none}",
      ".guide-panel{pointer-events:auto;width:min(336px,calc(100vw - 24px));max-height:calc(100vh - 32px - env(safe-area-inset-bottom,0px));overflow-y:auto;background:#fff;border:1px solid #e3e0d8;border-radius:20px;box-shadow:0 18px 50px rgba(25,25,33,.25);padding:16px;color:#23222b}",
      ".guide-panel[hidden]{display:none}",
      ".guide-head{display:flex;align-items:center;gap:10px}",
      ".guide-head img{width:44px;height:44px;border-radius:50%;object-fit:cover;object-position:center 8%;border:2px solid #f6d9d4;flex:none;background:#fdf3ec}",
      ".guide-head b{font-size:.95rem;display:block;line-height:1.25}",
      ".guide-head small{color:#8a877e;font-weight:600;font-size:.74rem}",
      ".guide-close{margin-left:auto;width:34px;height:34px;border-radius:50%;border:1px solid #e3e0d8;background:#fff;color:#55534d;display:grid;place-items:center;flex:none;font-size:.85rem;cursor:pointer}",
      ".guide-text{display:block;font-size:.92rem;line-height:1.6;margin:12px 0 0;max-height:none;overflow:visible;-webkit-line-clamp:none}",
      ".guide-chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:13px}",
      ".guide-chips button{border:1px solid #e3e0d8;background:#f6f4ef;color:#23222b;border-radius:999px;padding:7px 12px;font-size:.8rem;font-weight:700;min-height:2.3rem;cursor:pointer}",
      ".guide-chips button.guide-active{background:#d63a2f;border-color:#d63a2f;color:#fff}",
      ".guide-foot{display:flex;gap:8px;margin-top:13px;flex-wrap:wrap}",
      ".guide-voice{display:inline-flex;align-items:center;gap:7px;border:1px solid #e3e0d8;background:#f6f4ef;color:#23222b;border-radius:11px;padding:9px 12px;font-weight:700;font-size:.8rem;min-height:2.7rem;flex:none;cursor:pointer}",
      ".guide-voice svg{width:15px;height:15px;flex:none}",
      ".guide-voice[aria-pressed=\"false\"]{color:#8a877e}",
      ".guide-go{flex:1;background:#23222b;color:#fff;border:0;border-radius:11px;padding:10px 12px;font-weight:700;font-size:.88rem;min-height:2.7rem;cursor:pointer}",
      ".guide-go[hidden]{display:none}",
      ".guide-rest{flex:1 1 100%;border:0;background:transparent;color:#8a877e;font-weight:600;font-size:.78rem;padding:6px;min-height:2.2rem;text-decoration:underline;cursor:pointer}",
      ".guide-restore{position:fixed;right:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:90;display:inline-flex;align-items:center;gap:8px;border:1px solid #e3e0d8;background:#fff;color:#23222b;border-radius:999px;padding:7px 14px 7px 7px;font-weight:700;font-size:.82rem;box-shadow:0 10px 30px rgba(25,25,33,.25);min-height:2.8rem;cursor:pointer}",
      ".guide-restore[hidden]{display:none}",
      ".guide-restore img{width:32px;height:32px;border-radius:50%;object-fit:cover;object-position:center 8%;background:#fdf3ec}",
      ".guide-spot-overlay{position:fixed;z-index:94;border:4px solid #d63a2f;border-radius:14px;box-shadow:0 0 0 5px rgba(214,58,47,.28),0 0 34px 10px rgba(214,58,47,.45);pointer-events:none;box-sizing:border-box}",
      "@media (prefers-reduced-motion: reduce){",
      ".guide-otter .guide-body{animation:none!important}",
      ".guide-roam.guide-is-running .guide-dust{animation:none}",
      ".guide-otter{transition:none}",
      "}"
    ].join("\n");

    var style = document.createElement("style");
    style.id = "guide-style";
    style.textContent = css;
    document.head.appendChild(style);

    /* ---------------- DOM (injected) ---------------- */
    var root = document.createElement("div");
    root.setAttribute("data-guide-root", "1");
    root.innerHTML =
      '<div class="guide-wrap" id="guideWrap">' +
        '<div class="guide-panel" id="guidePanel" hidden role="dialog" aria-label="Bé Rái Cá — người dẫn đường">' +
          '<div class="guide-head">' +
            '<img src="' + IMG_SRC + '" alt="" />' +
            "<div><b>Bé Rái Cá</b><small>Người dẫn đường · chạy theo bạn khắp trang</small></div>" +
            '<button type="button" class="guide-close" id="guideClose" aria-label="Đóng người dẫn đường">✕</button>' +
          "</div>" +
          '<p class="guide-text" id="guideText" aria-live="polite"></p>' +
          '<div class="guide-chips" id="guideChips" aria-label="Chọn nơi muốn tới"></div>' +
          '<div class="guide-foot">' +
            '<button type="button" class="guide-voice" id="guideVoice" aria-pressed="true">' +
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 6 9H3v6h3l5 4z" fill="currentColor" stroke="none"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9.5 9.5 0 0 1 0 13"/></svg>' +
              "<span>Giọng đọc: Bật</span>" +
            "</button>" +
            '<button type="button" class="guide-go" id="guideGo" hidden>Dẫn mình tới đó →</button>' +
            '<button type="button" class="guide-rest" id="guideRest">Cho bé nghỉ một lát</button>' +
          "</div>" +
        "</div>" +
      "</div>" +
      '<div class="guide-roam" id="guideRoam">' +
        '<div class="guide-bubble" id="guideBubble" hidden>' +
          '<p id="guideBubbleText"></p>' +
          '<span class="guide-hint">Bấm vào mình để chọn nơi muốn tới nhé!</span>' +
          '<button type="button" class="guide-bubble-x" id="guideBubbleClose" aria-label="Đóng bong bóng thoại">✕</button>' +
        "</div>" +
        '<button type="button" class="guide-otter" id="guideOtterBtn" aria-label="Bé Rái Cá dẫn đường — bấm để được dẫn đi khắp trang" aria-expanded="false">' +
          '<span class="guide-otter-shadow" aria-hidden="true"></span>' +
          '<span class="guide-body"><img src="' + IMG_SRC + '" alt="Bé Rái Cá toàn thân: đủ tay chân, đội mũ nồi xanh, đeo ba lô hồng, đang vẫy tay chào" /></span>' +
          '<span class="guide-badge" id="guideBadge" aria-hidden="true">!</span>' +
        "</button>" +
        '<span class="guide-dust" aria-hidden="true"></span><span class="guide-dust guide-d2" aria-hidden="true"></span><span class="guide-dust guide-d3" aria-hidden="true"></span>' +
      "</div>" +
      '<button type="button" class="guide-restore" id="guideRestore" hidden>' +
        '<img src="' + IMG_SRC + '" alt="" /> Gọi Bé Rái Cá' +
      "</button>";
    document.body.appendChild(root);

    var guidePanel = document.getElementById("guidePanel");
    var guideTextEl = document.getElementById("guideText");
    var guideChips = document.getElementById("guideChips");
    var guideGo = document.getElementById("guideGo");
    var guideVoice = document.getElementById("guideVoice");
    var guideBadge = document.getElementById("guideBadge");
    var roam = document.getElementById("guideRoam");
    var otterBtn = document.getElementById("guideOtterBtn");
    var roamBubble = document.getElementById("guideBubble");
    var roamBubbleText = document.getElementById("guideBubbleText");
    var otterRestore = document.getElementById("guideRestore");
    if (!guidePanel || !roam || !otterBtn) return;

    var voiceOn = true, currentDest = null, typeTimer = null;

    var GREETING =
      "你好 (nǐ hǎo) bạn! Mình là Bé Rái Cá — người dẫn đường của bạn trong web này. " +
      "Bạn muốn tới chỗ nào, cứ bấm một nút bên dưới: mình vừa chạy dẫn đường, vừa đọc to giới thiệu cho bạn nghe luôn!";

    /* Destinations mapped to REAL sections of index2.html (selectors verified
       against the live file). `screen` = the site's data-otter2-screen panel
       that must be active for the target to be visible; the guide switches
       screens by clicking the site's own nav buttons. */
    var dests = [
      { key: "journey", label: "Hành trình HSK", selector: "#otter2HskJourney", screen: "home",
        reveal: [{ click: "#otter2OpenVocabBankBtn", until: "#otter2HskJourney" }],
        frameFallback: "#otter2OpenVocabBankBtn",
        text: "Đây là Hành trình HSK — bản đồ leo núi từ HSK 1 tới HSK 9 theo chuẩn HSK 3.0 mới nhất. Mỗi chặng là một cấp độ, học xong chặng này mình lại leo tiếp chặng sau!",
        arrive: "Tới Hành trình HSK rồi! Bạn đang ở những chặng đầu tiên — bấm vào một chặng để xem mình sẽ học những gì nhé." },
      { key: "vocab", label: "Kho từ vựng", selector: "#otter2Hsk1Workspace", screen: "home",
        reveal: [{ click: "#otter2OpenVocabBankBtn", until: "#otter2HskJourney" },
                 { click: "#otter2HskLevelRow [data-otter2-hsk=\"1\"]", until: "#otter2Hsk1Workspace" }],
        frameFallback: "#otter2OpenVocabBankBtn",
        text: "Kho từ vựng HSK có hơn 11.000 từ của cả 9 cấp độ: mỗi từ có chữ Hán, pinyin, nghĩa tiếng Việt và câu ví dụ, lại còn nghe được phát âm nữa.",
        arrive: "Tới kho từ vựng rồi! Bạn chọn cấp độ HSK ở hàng nút phía trên, rồi bấm vào từng thẻ từ để xem chi tiết và nghe đọc mẫu nhé." },
      { key: "dict", label: "Tra từ điển", selector: "#otter2DictRoot", screen: "vocab",
        text: "Từ điển tra cứu nhanh: gõ chữ Hán, pinyin hay nghĩa tiếng Việt đều tìm được từ, kèm cách đọc và ví dụ minh hoạ.",
        arrive: "Tới từ điển rồi! Bạn gõ thử một từ vào ô tìm kiếm — ví dụ 北京 (Bắc Kinh) — xem sao nhé." },
      { key: "practice", label: "Luyện tập", selector: "#otter2PracticeHub", screen: "reading",
        text: "Khu luyện tập có đủ món: luyện nghe, luyện đọc, ghép từ, gõ chữ và phản xạ nhanh — học xong từ vựng thì qua đây vận động cho nhớ lâu.",
        arrive: "Tới khu luyện tập rồi! Bạn chọn một kiểu luyện ở đây và làm thử vài câu nhé, sai cũng không sao đâu." },
      { key: "auto", label: "Học tự động", selector: "#otter2AutoHub", screen: "auto",
        text: "Chế độ Học tự động (Auto) sẽ tự chạy bài học cho bạn: từ vựng, câu ví dụ nối tiếp nhau — hợp lúc bạn muốn ôn nhẹ nhàng mà không cần bấm nhiều.",
        arrive: "Tới khu Học tự động rồi! Bạn chọn gói học rồi bấm chạy, để máy tự dẫn bài cho mình nhé." },
      { key: "flash", label: "Thẻ ghi nhớ", selector: "#otter2FeatFlashcard", screen: "home",
        text: "Thẻ ghi nhớ (flashcard) giúp bạn ôn từ theo kiểu lật thẻ: nhìn chữ Hán, đoán pinyin và nghĩa, rồi lật lại kiểm tra — ôn nhanh mà nhớ rất lâu.",
        arrive: "Đây là lối vào Thẻ ghi nhớ nè! Bấm vào thẻ để bắt đầu ôn từ theo kiểu lật thẻ nhé." },
      { key: "fb", label: "Cộng đồng Facebook", selector: ".otter2-fb-banner", screen: "home",
        text: "Cộng đồng Thích Tiếng Trung 3.0 trên Facebook đăng bài học mới mỗi ngày lúc 19:30: video bài khoá, audio phát âm và file PDF tập viết chữ Hán miễn phí.",
        arrive: "Đây là banner cộng đồng Facebook nè! Bấm nút Theo dõi trang để nhận bài học mới mỗi ngày lúc 19:30 nhé." },
      { key: "voice", label: "Giọng đọc", selector: "#otter2VoiceSystemBtn", screen: "home",
        text: "Hệ thống giọng đọc cho bạn chọn giọng đọc tiếng Trung và chỉnh tốc độ đọc — đọc chậm lại một chút sẽ dễ nghe và bắt chước theo hơn đó.",
        arrive: "Nút Hệ thống giọng đọc ở đây nè! Bấm vào để chọn giọng và tốc độ đọc hợp với bạn nhé." },
      { key: "chat", label: "Chat Online", selector: "#otter2ChatOnlineBtn", screen: null,
        text: "Nút Chat Online ở thanh trên cùng để bạn nhắn tin trao đổi ngay trong cộng đồng học tiếng Trung.",
        arrive: "Nút Chat Online là nút bong bóng chat ở thanh trên cùng đó — bấm vào là nhắn tin được ngay!" },
      { key: "premium", label: "Premium", selector: "#otter2PremiumBtn", screen: null, special: "premium",
        text: "Gói Premium mở khoá toàn bộ tính năng nâng cao: luyện tập không giới hạn, lộ trình đầy đủ và nhiều nội dung chuyên sâu hơn.",
        arrive: "Nút Premium ở thanh trên cùng nè! Bấm vào để xem các gói và quyền lợi nhé.",
        arriveHidden: "Nút Premium nằm ở thanh menu trên cùng của trang — khi nút chưa hiện, bạn mở menu tài khoản ở góc trên sẽ thấy mục Premium ở đó nhé!" }
    ];

    /* ---------------- Speech + typing ---------------- */
    function typeText(text) {
      clearInterval(typeTimer);
      if (reducedMotion) { guideTextEl.textContent = text; return; }
      guideTextEl.textContent = "";
      var i = 0;
      /* Long descriptions type in bigger steps so the full text lands in
         about a second — at a flat 2 chars/tick a ~190-char description
         spent ~1.5s visibly "truncated" mid-word while typing. */
      var step = Math.max(2, Math.ceil(text.length / 55));
      typeTimer = setInterval(function () {
        i += step;
        guideTextEl.textContent = text.slice(0, i);
        if (i >= text.length) clearInterval(typeTimer);
      }, 16);
    }
    function speak(text) {
      if (!voiceOn || !("speechSynthesis" in window)) return;
      try {
        window.speechSynthesis.cancel();
        var clean = text
          .replace(/你好/g, "ní hảo")
          .replace(/北京/g, "Bắc Kinh")
          .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}]/gu, "")
          .replace(/\s+/g, " ")
          .trim();
        var u = new SpeechSynthesisUtterance(clean);
        u.lang = "vi-VN";
        u.rate = 1;
        var voices = window.speechSynthesis.getVoices() || [];
        for (var i = 0; i < voices.length; i++) {
          if (voices[i].lang && voices[i].lang.toLowerCase().indexOf("vi") === 0) { u.voice = voices[i]; break; }
        }
        window.speechSynthesis.speak(u);
      } catch (e) { /* device has no TTS — the speech bubble still shows the text */ }
    }
    function say(text) {
      typeText(text);
      speak(text);
      if (guidePanel.hidden && !roam.hidden) showBubble(text, 7000);
    }

    /* ---------------- Destination chips ---------------- */
    dests.forEach(function (d) {
      var b = document.createElement("button");
      b.type = "button";
      b.textContent = d.label;
      b.setAttribute("aria-pressed", "false");
      b.addEventListener("click", function () {
        currentDest = d;
        var btns = guideChips.querySelectorAll("button");
        for (var i = 0; i < btns.length; i++) {
          btns[i].classList.remove("guide-active");
          btns[i].setAttribute("aria-pressed", "false");
        }
        b.classList.add("guide-active");
        b.setAttribute("aria-pressed", "true");
        guideGo.hidden = false;
        guideGo.textContent = "Dẫn mình tới đó →";
        say(d.text);
      });
      guideChips.appendChild(b);
    });

    guideGo.addEventListener("click", function () {
      if (!currentDest) return;
      guideTrip(currentDest);
    });

    /* ---------------- Roaming engine ---------------- */
    var pos = { x: 0, y: 0 }, rafId = null, bubbleTimer = null;
    var parkUntil = 0, lastPark = 0, lastDash = 0, lastScrollY = window.scrollY || 0;
    var tripActive = false, roamTimer = null, roamIdx = 0;

    function clampNum(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
    function roamW() { return roam.offsetWidth || 118; }
    function roamH() { return roam.offsetHeight || 150; }
    /* Lộ trình fullscreen đang mở? (module gốc gắn .ttc-path-fs cho panel
       đã portal ra body + khoá cuộn bằng body.ttc-path-fs-lock) */
    function pathFsActive() {
      try {
        if (document.body && document.body.classList.contains("ttc-path-fs-lock")) return true;
        var p = document.getElementById("ttcPathPanel");
        return !!(p && p.classList.contains("ttc-path-fs"));
      } catch (e) { return false; }
    }
    function dockY() {
      /* Trong phiên lộ trình fullscreen: neo bé ở DẢI TRÊN CÙNG (phía trên
         khu câu hỏi/bài đọc) thay vì góc dưới — theo yêu cầu chủ web. */
      if (pathFsActive()) return 4;
      var m = window.innerWidth <= 720 ? 4 : 12; return Math.max(6, window.innerHeight - roamH() - m);
    }
    function dockX(side) { return side === "left" ? 12 : Math.max(8, window.innerWidth - roamW() - 14); }
    function applyPos() { roam.style.transform = "translate(" + pos.x + "px," + pos.y + "px)"; }
    function setFace(dx) {
      if (dx < -4) otterBtn.classList.add("guide-face-left");
      else if (dx > 4) otterBtn.classList.remove("guide-face-left");
    }
    function jumpOtter() {
      if (reducedMotion) return;
      roam.classList.remove("guide-is-jumping");
      void roam.offsetWidth;
      roam.classList.add("guide-is-jumping");
      setTimeout(function () { roam.classList.remove("guide-is-jumping"); }, 660);
    }
    function runTo(tx, ty, done) {
      tx = clampNum(tx, 4, Math.max(4, window.innerWidth - roamW() - 4));
      ty = clampNum(ty, 4, Math.max(4, window.innerHeight - roamH() - 4));
      if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
      var sx = pos.x, sy = pos.y, dx = tx - sx, dy = ty - sy;
      var dist = Math.sqrt(dx * dx + dy * dy);
      setFace(dx);
      if (reducedMotion || dist < 6) {
        pos.x = tx; pos.y = ty; applyPos();
        roam.classList.remove("guide-is-running");
        placeBubble();
        if (done) done();
        return;
      }
      roam.classList.add("guide-is-running");
      var dur = clampNum(dist / 0.55, 350, 1700), t0 = null;
      function step(ts) {
        if (!t0) t0 = ts;
        var k = Math.min(1, (ts - t0) / dur);
        pos.x = sx + dx * k;
        pos.y = sy + dy * k - (dist > 240 ? Math.sin(k * Math.PI) * 16 : 0);
        applyPos();
        if (k < 1) { rafId = requestAnimationFrame(step); }
        else {
          pos.y = ty; applyPos();
          roam.classList.remove("guide-is-running");
          rafId = null;
          placeBubble();
          if (done) done();
        }
      }
      rafId = requestAnimationFrame(step);
    }
    /* Position the speech bubble so it always stays inside the viewport.
       The old code anchored the fixed 238px bubble to the 118px roam box
       with a two-state flip chosen once by `pos.x < 170`, and never measured
       the bubble's own rect — so on narrow screens (or after the otter moved
       while the bubble was up) it stuck out past the right edge and the text
       was clipped. Now: measure the bubble, prefer right-anchored (extending
       left from the otter), flip to left-anchored when that would overflow
       the left edge, then clamp the final position into the viewport with a
       6px margin. The asymmetric corner (the "tail") goes on whichever side
       is nearest the otter. */
    function placeBubble() {
      if (roamBubble.hidden) return;
      var bw = roamBubble.offsetWidth || 238;
      var vw = window.innerWidth;
      var otterCx = pos.x + roamW() / 2;
      var leftEdge = pos.x + roamW() + 4 - bw; /* right-anchored: extends left */
      if (leftEdge < 6) leftEdge = pos.x - 4;  /* left-anchored: extends right */
      leftEdge = clampNum(leftEdge, 6, Math.max(6, vw - bw - 6));
      roamBubble.style.left = (leftEdge - pos.x) + "px";
      roamBubble.style.right = "auto";
      roam.classList.toggle("guide-bubble-left", leftEdge + bw / 2 > otterCx);
    }
    function showBubble(text, ms) {
      roamBubbleText.textContent = text;
      roamBubble.hidden = false;
      placeBubble();
      clearTimeout(bubbleTimer);
      if (ms) bubbleTimer = setTimeout(function () { roamBubble.hidden = true; }, ms);
    }
    function hideBubble() { roamBubble.hidden = true; clearTimeout(bubbleTimer); }

    /* The otter only stands on margins / corners / empty spots — check the
       point under its centre is not an interactive or learning element. */
    var BLOCK_SEL = "button,a,input,textarea,select,canvas,[contenteditable='true'],.otter2-feature,.otter2-node,[role='dialog'],[data-guide-root]";
    function spotFree(x, y) {
      try {
        var el = document.elementFromPoint(x + roamW() / 2, y + roamH() / 2);
        if (!el) return false;
        if (el === document.body || el === document.documentElement) return true;
        return !el.closest || !el.closest(BLOCK_SEL);
      } catch (e) { return false; }
    }
    function isVisible(el) {
      if (!el) return false;
      var r = el.getBoundingClientRect();
      if (!r || r.width === 0 || r.height === 0) return false;
      var cs = window.getComputedStyle ? window.getComputedStyle(el) : null;
      return !cs || (cs.display !== "none" && cs.visibility !== "hidden");
    }

    /* The element the user should actually look at: when the destination is
       a very large container (bounding box much larger than the viewport),
       its first visible child card/section is what gets framed and what the
       otter lands next to. */
    function visibleCard(el) {
      try {
        var r = el.getBoundingClientRect();
        if (r.width > window.innerWidth * 1.02 || r.height > window.innerHeight * 1.15) {
          var kids = el.querySelectorAll("*");
          var limit = Math.min(kids.length, 400);
          for (var i = 0; i < limit; i++) {
            var k = kids[i];
            if (!isVisible(k)) continue;
            var kr = k.getBoundingClientRect();
            if (kr.width >= 120 && kr.height >= 40 && kr.width <= window.innerWidth && kr.height <= window.innerHeight) {
              return k;
            }
          }
        }
      } catch (e) {}
      return el;
    }

    /* Arrival highlight — drawn as ONE fixed-position overlay ring over the
       target, never as a style ON the target. Why the old approach (inline
       outline + WAAPI box-shadow pulse on the target element itself) was
       invisible in live tests:
         1. It fired on a fixed clock (450ms after the nav click, 680ms
            after scrollIntoView) with no check that a screen-switch target
            had actually rendered or that scrolling had settled — the 2.6s
            pulse could play entirely while the target was off-screen.
         2. A box-shadow/outline ON the target is clipped by any
            overflow:hidden ancestor, and for the full-viewport containers
            used as targets the ring sits on the container's outer edges —
            top/bottom off-screen, left/right flush with the viewport edge.
            WAAPI box-shadow also loses to the site theme's
            `box-shadow: ... !important` rules (animations sit below
            !important author styles in the cascade).
       The overlay lives in the guide's own root (no clipping ancestor),
       starts only once the target is confirmed visible, and tracks the
       target's rect every animation frame so scrolling can't detach it. */
    var spotOverlay = null, spotRaf = null, spotCleanupTimer = null;
    function removeSpotOverlay() {
      if (spotRaf) { cancelAnimationFrame(spotRaf); spotRaf = null; }
      clearTimeout(spotCleanupTimer); spotCleanupTimer = null;
      if (spotOverlay && spotOverlay.parentNode) spotOverlay.parentNode.removeChild(spotOverlay);
      spotOverlay = null;
    }
    function rectInView(r) {
      return !!r && r.width > 0 && r.height > 0 &&
        r.bottom > 0 && r.right > 0 &&
        r.top < window.innerHeight && r.left < window.innerWidth;
    }

    /* The element to frame: the target's visible card (see visibleCard) —
       but never an element without a layout box. If the chosen card's
       rect is empty (it sits in a still-hidden or not-yet-rendered
       subtree), fall back to the first descendant that genuinely has a
       box. Returns null when nothing framable exists; the caller then
       draws nothing, because a zero-size ring is worse than none. */
    function pickFrameTarget(el) {
      var card = visibleCard(el);
      var r = null;
      try { r = card.getBoundingClientRect(); } catch (e) {}
      if (r && r.width > 0 && r.height > 0) return card;
      try {
        var kids = el.querySelectorAll("*");
        var limit = Math.min(kids.length, 400);
        for (var i = 0; i < limit; i++) {
          if (isVisible(kids[i])) return kids[i];
        }
      } catch (e) {}
      return null;
    }

    function highlightTarget(el) {
      if (!el) return;
      removeSpotOverlay();
      var card = pickFrameTarget(el);
      if (!card) return;
      var ov = document.createElement("div");
      ov.className = "guide-spot-overlay";
      ov.setAttribute("aria-hidden", "true");
      root.appendChild(ov);
      spotOverlay = ov;
      function place() {
        if (!spotOverlay) return;
        var r = card.getBoundingClientRect();
        if (!r || r.width === 0 || r.height === 0) { removeSpotOverlay(); return; }
        ov.style.left = (r.left - 6) + "px";
        ov.style.top = (r.top - 6) + "px";
        ov.style.width = (r.width + 12) + "px";
        ov.style.height = (r.height + 12) + "px";
      }
      place();
      /* Self-verify: if the framed element lies outside the viewport —
         e.g. a tall target was scrolled to center but its first card
         ended up above the fold — scroll the CARD itself into view and
         recompute; the rAF tracker below follows its live rect every
         frame, so the ring stays glued to it while the page moves.
         The overlay is therefore never left sitting fully off-screen. */
      requestAnimationFrame(function () {
        if (!spotOverlay) return;
        if (!rectInView(card.getBoundingClientRect())) {
          try { card.scrollIntoView({ behavior: reducedMotion ? "auto" : "smooth", block: "center" }); }
          catch (e) { try { card.scrollIntoView(); } catch (e2) {} }
        }
      });
      function track() {
        place();
        if (spotOverlay) spotRaf = requestAnimationFrame(track);
      }
      spotRaf = requestAnimationFrame(track);
      spotCleanupTimer = setTimeout(removeSpotOverlay, 2950); /* safety net */
      if (!reducedMotion && ov.animate) {
        try {
          var anim = ov.animate([
            { transform: "scale(1)", boxShadow: "0 0 0 3px rgba(214,58,47,.35),0 0 18px 4px rgba(214,58,47,.35)" },
            { transform: "scale(1.015)", boxShadow: "0 0 0 7px rgba(214,58,47,.30),0 0 42px 14px rgba(214,58,47,.55)" },
            { transform: "scale(1)", boxShadow: "0 0 0 3px rgba(214,58,47,.35),0 0 18px 4px rgba(214,58,47,.35)" }
          ], { duration: 1400, iterations: 2, easing: "ease-in-out" });
          if (anim) anim.onfinish = removeSpotOverlay;
        } catch (e) {}
      }
      /* No WAAPI (or reduced motion): the overlay's static CSS ring stays
         for ~2.8s via the cleanup timer above. */
    }
    /* Switch the site's own screens using its own nav buttons. */
    function ensureScreen(name, cb) {
      if (!name) { cb(); return; }
      var panel = null;
      try { panel = document.querySelector('[data-otter2-screen-panel="' + name + '"]'); } catch (e) {}
      if (panel && !panel.hidden) { cb(); return; }
      var btn = null;
      try {
        btn = document.querySelector('#otter2NavLinks [data-otter2-screen="' + name + '"]') ||
              document.querySelector('[data-otter2-screen="' + name + '"]');
      } catch (e) {}
      if (btn) {
        try { btn.click(); } catch (e) {}
        setTimeout(cb, reducedMotion ? 60 : 450);
      } else {
        cb();
      }
    }

    /* Poll until the destination is genuinely rendered (every 200ms, up to
       ~3s): the element must exist, have a non-empty rect, be laid out in a
       visible panel (offsetParent non-null — screen panels toggle `hidden`)
       and pass the computed display/visibility check. Essential for
       screen-switch destinations, whose panels render asynchronously after
       the nav click; the old one-shot check + fixed delays let the trip
       (and its highlight) run against a target that was not on screen yet. */
    function waitVisible(selector, cb) {
      var tries = 0;
      function check() {
        var el = null;
        try { el = document.querySelector(selector); } catch (e) {}
        var ok = false;
        if (el && isVisible(el)) {
          try { ok = el.offsetParent !== null || window.getComputedStyle(el).position === "fixed"; }
          catch (e) { ok = true; }
        }
        if (ok) { cb(el); return; }
        tries++;
        if (tries >= 15) { cb(null); return; }
        setTimeout(check, 200);
      }
      check();
    }

    /* Wait until the target's rect stops moving (smooth scroll finished):
       two consecutive samples within 2px, sampled every 130ms, ~1.4s max. */
    function waitSettled(el, cb) {
      if (reducedMotion) { cb(); return; }
      var lastTop = null, stable = 0, tries = 0;
      function check() {
        var r = el.getBoundingClientRect();
        if (lastTop !== null && Math.abs(r.top - lastTop) < 2) stable++;
        else stable = 0;
        lastTop = r.top;
        tries++;
        if (stable >= 2 || tries >= 11) { cb(); return; }
        setTimeout(check, 130);
      }
      setTimeout(check, 60);
    }

    /* Reveal step for toggle-open destinations. Some targets start with
       the `hidden` attribute and appear only after the learner clicks a
       control — Kho từ vựng is the extreme case: #otter2Hsk1Workspace
       sits inside the also-hidden #otter2HskJourney; the journey opens
       via #otter2OpenVocabBankBtn, and the workspace itself opens via a
       level-node click that runs the site's async openHskLevel(). The
       trip previously had NO reveal step, so for these destinations
       waitVisible() always timed out and guideTrip silently degraded to
       its not-found fallback (description bubble + dock at bottom-right)
       — highlightTarget() was never reached, which is exactly why the
       Luyện tập trip (a plain screen switch) showed the red frame and
       the Kho từ vựng trip never did. Each reveal step clicks its
       control ONLY while its `until` element is still hidden — both
       controls are toggles, so clicking an already-open one would close
       it again — then polls briefly for the reveal to take effect. */
    function ensureRevealed(dest, cb) {
      var target = null;
      try { target = document.querySelector(dest.selector); } catch (e) {}
      if (target && isVisible(target)) { cb(); return; }
      var steps = dest.reveal || [];
      var i = 0;
      function next() {
        if (i >= steps.length) { cb(); return; }
        var step = steps[i++];
        var untilEl = null;
        try { untilEl = step.until ? document.querySelector(step.until) : null; } catch (e) {}
        if (untilEl && isVisible(untilEl)) { next(); return; }
        var btn = null;
        try { btn = document.querySelector(step.click); } catch (e) {}
        if (btn) { try { btn.click(); } catch (e) {} }
        var waited = 0;
        (function poll() {
          var u = null;
          try { u = step.until ? document.querySelector(step.until) : null; } catch (e) {}
          if ((u && isVisible(u)) || waited >= 1200) { next(); return; }
          waited += 150;
          setTimeout(poll, 150);
        })();
      }
      next();
    }

    /* Shared trip ending: scroll the element into view, wait for its
       rect to settle, run the otter to a free spot hugging its visible
       card, then — at arrival — frame it and speak the arrival line
       together. Used for the real target and, when the target can never
       appear (e.g. the vocab workspace behind the site's login gate),
       for the destination's toggle control instead, so the learner
       still ends up looking at a framed, visible thing. */
    function arriveAt(el, dest) {
      try {
        el.scrollIntoView({ behavior: reducedMotion ? "auto" : "smooth", block: "center" });
      } catch (e) { el.scrollIntoView(); }
      say("Mình chạy trước dẫn đường đây — bạn theo mình nhé!");
      waitSettled(el, function () {
        /* Fresh geometry, only now that the screen has switched, any
           reveal has rendered and the scroll has settled. Landing spots
           hug the target's visible card: just BELOW it first, then
           right, then left; the corners are only a last resort
           (previously a stale rect plus spotFree() rejecting the
           bottom-right corner dropped the otter in the far bottom-left). */
        var card = visibleCard(el);
        var r = card.getBoundingClientRect();
        var W = roamW(), H = roamH(), vw = window.innerWidth, vh = window.innerHeight;
        var sideY = clampNum(r.top + r.height / 2 - H / 2, 6, Math.max(6, vh - H - 8));
        var belowX = clampNum(r.left + r.width / 3 - W / 2, 8, Math.max(8, vw - W - 8));
        var belowY = clampNum(r.bottom + 10, 6, Math.max(6, vh - H - 8));
        var cands = [
          [belowX, belowY],
          [r.right + 8, sideY],
          [r.left - W - 8, sideY],
          [vw - W - 12, vh - H - 12],
          [12, vh - H - 12]
        ];
        var tx = cands[3][0], ty = cands[3][1];
        for (var i = 0; i < cands.length; i++) {
          var cx = clampNum(cands[i][0], 4, Math.max(4, vw - W - 4));
          var cy = clampNum(cands[i][1], 4, Math.max(4, vh - H - 4));
          if (spotFree(cx, cy)) { tx = cx; ty = cy; break; }
        }
        runTo(tx, ty, function () {
          jumpOtter();
          if (tx + W / 2 < r.left + r.width / 2) otterBtn.classList.remove("guide-face-left");
          else otterBtn.classList.add("guide-face-left");
          /* Highlight + arrival line start together, at arrival. */
          highlightTarget(el);
          if (dest.arrive) say(dest.arrive);
          tripActive = false;
        });
      });
    }

    function guideTrip(dest) {
      tripActive = true;
      closeGuide(true);
      ensureScreen(dest.screen, function () {
        ensureRevealed(dest, function () {
          waitVisible(dest.selector, function (el) {
            if (el) { arriveAt(el, dest); return; }
            /* Target never appeared (e.g. the Premium button before
               login, or the vocab workspace behind the site's login
               gate): if the destination names a toggle control, frame
               THAT instead — it is the visible thing the learner should
               notice — otherwise explain where the target lives instead
               of scrolling nowhere, and dock. */
            var fb = null;
            try { fb = dest.frameFallback ? document.querySelector(dest.frameFallback) : null; } catch (e) {}
            if (fb && isVisible(fb)) { arriveAt(fb, dest); return; }
            say(dest.arriveHidden || dest.text);
            runTo(dockX("right"), dockY());
            tripActive = false;
          });
        });
      });
    }

    /* ---------------- Non-interference: park while the user is learning ---------------- */
    var LEARN_SEL = "#otter2Hsk1Workspace,#otter2DictRoot,#otter2DictDetail,#otter2PracticeHub,#otter2PracticePanels,#otter2AutoHub,#otter2AutoPanels,#flashcardSection,#ttcPathPanel";
    function parkOtter() {
      var now = Date.now();
      parkUntil = now + 5000;
      if (now - lastPark < 1600 || roam.hidden) return;
      lastPark = now;
      hideBubble();
      var tx = pathFsActive() ? 10 : ((pos.x + roamW() / 2 < window.innerWidth / 2) ? 10 : dockX("right"));
      runTo(tx, dockY());
    }
    function onUserInteract(ev) {
      var t = ev.target;
      if (!t || t.nodeType !== 1 || !t.closest) return;
      if (t.closest("[data-guide-root]")) return;
      try {
        if (t.closest("input,textarea,select,canvas,[contenteditable='true']") || t.closest(LEARN_SEL)) {
          parkOtter();
        }
      } catch (e) {}
    }
    document.addEventListener("pointerdown", onUserInteract, true);
    document.addEventListener("focusin", onUserInteract, true);

    /* Follow along on big scrolls: dash a short hop, then jump. */
    var scrollTick = null, scrollDimTimer = null;
    window.addEventListener("scroll", function () {
      /* While scrolling is active, fade the otter to 45% and shrink it so
         the bottom-docked otter never covers buttons/titles moving under
         it; restore 600ms after scrolling stops. This cannot fight the
         run/trip animations: opacity is on .guide-roam (runTo only writes
         its `transform`), and the shrink uses the independent CSS `scale`
         property on .guide-otter (the body's keyframe animations use
         `transform`, and the face-flip uses `scale` on .guide-body — a
         different element). On viewports <640px the otter also defaults
         to 0.78 scale via CSS. */
      if (!roam.hidden) {
        roam.classList.add("guide-scrolling");
        clearTimeout(scrollDimTimer);
        scrollDimTimer = setTimeout(function () { roam.classList.remove("guide-scrolling"); }, 600);
      }
      var y = window.scrollY || 0;
      var delta = Math.abs(y - lastScrollY);
      lastScrollY = y;
      if (scrollTick) return;
      scrollTick = setTimeout(function () {
        scrollTick = null;
        var now = Date.now();
        if (delta > 240 && now - lastDash > 4000 && guidePanel.hidden && !roam.hidden && now > parkUntil) {
          lastDash = now;
          var dir = Math.random() < 0.5 ? -1 : 1;
          runTo(pos.x + dir * (110 + Math.random() * 90), dockY(), jumpOtter);
        }
      }, 160);
    }, { passive: true });

    /* Idle roaming: every 6–10s the otter visibly RUNS (run animation +
       dust, ~1–2s per trip via runTo's distance-based duration) along the
       bottom strip to a clearly different anchor — about 12%, 45% and 80%
       of the viewport width, then back home — pauses there a few seconds
       with its idle bounce, and later runs on again. Anchors whose landing
       spot is not free are skipped. Park-on-interaction, an open panel, a
       guided trip and reduced motion all override roaming; a hidden tab
       pauses the schedule and visibilitychange resumes it. */
    var ROAM_ANCHORS = [0.12, 0.45, 0.8];
    function roamAnchorX(i) {
      if (i >= ROAM_ANCHORS.length) return dockX("right"); /* back home */
      return clampNum(Math.round(ROAM_ANCHORS[i] * window.innerWidth - roamW() / 2), 8, Math.max(8, window.innerWidth - roamW() - 8));
    }
    function scheduleRoam(delay) {
      clearTimeout(roamTimer);
      if (reducedMotion) { roamTimer = null; return; }
      roamTimer = setTimeout(roamStep, delay == null ? 6000 + Math.random() * 4000 : delay);
    }
    function roamStep() {
      roamTimer = null;
      var now = Date.now();
      if (document.hidden) { scheduleRoam(4000); return; }
      if (!guidePanel.hidden || roam.hidden || rafId || tripActive || now < parkUntil) { scheduleRoam(); return; }
      for (var tries = 0; tries <= ROAM_ANCHORS.length; tries++) {
        var idx = roamIdx % (ROAM_ANCHORS.length + 1);
        roamIdx++;
        var tx = roamAnchorX(idx), ty = dockY();
        if (Math.abs(tx - pos.x) < 60) continue; /* already there — take the next anchor */
        if (!spotFree(tx, ty)) continue; /* never run onto interactive content */
        runTo(tx, ty, jumpOtter);
        break;
      }
      scheduleRoam();
    }
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) { clearTimeout(roamTimer); roamTimer = null; }
      else scheduleRoam(2500);
    });
    scheduleRoam(5000);

    window.addEventListener("resize", function () {
      pos.x = clampNum(pos.x, 4, Math.max(4, window.innerWidth - roamW() - 4));
      pos.y = clampNum(pos.y, 4, Math.max(4, window.innerHeight - roamH() - 4));
      applyPos();
      placeBubble();
    });

    /* ---------------- Panel open / close / rest / recall ---------------- */
    function openGuide() {
      guidePanel.hidden = false;
      hideBubble();
      guideBadge.style.display = "none";
      otterBtn.setAttribute("aria-expanded", "true");
      /* Move aside to the bottom-left so the otter never covers the panel. */
      runTo(dockX("left"), dockY(), jumpOtter);
      say(GREETING);
    }
    function closeGuide(skipDock) {
      guidePanel.hidden = true;
      otterBtn.setAttribute("aria-expanded", "false");
      clearInterval(typeTimer);
      if ("speechSynthesis" in window) { try { window.speechSynthesis.cancel(); } catch (e) {} }
      if (!skipDock && !roam.hidden) runTo(dockX("right"), dockY());
    }
    otterBtn.addEventListener("click", function () {
      if (roam.hidden) return;
      if (guidePanel.hidden) { jumpOtter(); openGuide(); }
      else closeGuide();
    });
    document.getElementById("guideClose").addEventListener("click", function () { closeGuide(); });
    document.getElementById("guideRest").addEventListener("click", function () {
      closeGuide(true);
      roam.hidden = true;
      hideBubble();
      otterRestore.hidden = false;
    });
    otterRestore.addEventListener("click", function () {
      otterRestore.hidden = true;
      roam.hidden = false;
      pos.x = dockX("right"); pos.y = dockY(); applyPos();
      jumpOtter();
      showBubble("Mình quay lại rồi nè! Bấm vào mình, mình chạy dẫn bạn đi tiếp nhé.", 6000);
    });
    roamBubble.addEventListener("click", function (evt) {
      if (evt.target.id === "guideBubbleClose") return;
      if (guidePanel.hidden) openGuide();
    });
    document.getElementById("guideBubbleClose").addEventListener("click", function (evt) {
      evt.stopPropagation();
      hideBubble();
    });
    guideVoice.addEventListener("click", function () {
      voiceOn = !voiceOn;
      guideVoice.setAttribute("aria-pressed", voiceOn ? "true" : "false");
      guideVoice.querySelector("span").textContent = voiceOn ? "Giọng đọc: Bật" : "Giọng đọc: Tắt";
      if (!voiceOn) {
        if ("speechSynthesis" in window) { try { window.speechSynthesis.cancel(); } catch (e) {} }
      } else if (guideTextEl.textContent) {
        speak(guideTextEl.textContent);
      }
    });

    /* ---------------- Start: docked bottom-right ---------------- */
    pos.x = dockX("right"); pos.y = dockY(); applyPos();
    setTimeout(function () {
      if (guidePanel.hidden && !roam.hidden) {
        showBubble("你好！Mình là Bé Rái Cá — giờ mình có đủ chân tay rồi nè! Bấm vào mình, mình chạy dẫn bạn đi khắp web, tới nơi là mình nhảy lên chỉ cho bạn thấy.", 11000);
      }
    }, 1200);

    /* ---------------- Bé Rái Cá NHẮC HỌC (study buddy, additive) ----------------
       Dùng lại cơ chế sẵn có của guide: say() (bong bóng + giọng đọc tôn trọng
       voiceOn), jumpOtter(), trạng thái ẩn roam.hidden, LEARN_SEL, parkUntil,
       tripActive. Tiến độ THẬT đọc từ localStorage "otter2_hsk_vocab_progress_v1"
       (định dạng engine ghi: { "<cấp>": { detailIndex, learned: [chữ Hán...] } };
       đếm tương thích cả dạng { "<cấp>": { "<từ>": 1 } }). Trạng thái nhắc học
       lưu ở key riêng "otter2_guide_study_v1": { date, base, goal, lastVisit,
       enabled, idleNudges, cheered5, cheeredGoal, pathGoalMark }.
       base = tổng từ đã học tại lần mở đầu tiên của ngày -> learnedToday =
       tổng hiện tại - base (store gốc không có mốc thời gian từng từ nên đây
       là cách tính "hôm nay" trung thực nhất có thể). */
    try { initStudyBuddy(); } catch (eStudy) {
      if (window.console && console.warn) console.warn("Study buddy off:", eStudy);
    }

    /* ---------------- Bé Rái Cá VÀO TRONG LỘ TRÌNH fullscreen (additive, 2026-11-17) ----------------
       Vấn đề: khung fullscreen của lộ trình có z-index 2147482000
       (otter2-vocab-roadmap.css) trong khi guide chỉ ở lớp 90-95 -> bé bị che
       kín, bong bóng khen/nhắc của study-buddy cũng không ai thấy.
       Cách xử lý (chỉ khi body có .ttc-path-fs-lock, ngoài fs giữ nguyên 100%):
       - CSS nâng lớp roam/wrap/restore/overlay lên 2147482999-2147483001
         (trên lớp fs, dưới giới hạn z-index của trình duyệt).
       - dockY() đã fs-aware: bé neo ở DẢI TRÊN CÙNG và chạy dọc mép trên;
         park khi người học thao tác -> góc trên-trái (khu tiêu đề, không nút).
       - Bong bóng lật xuống DƯỚI bé (ở trên cùng mà bong bóng mở lên trên
         thì ra ngoài màn hình).
       - Watcher 700ms: vừa vào phiên -> bé chạy lên dải trên + nhảy chào;
         thoát phiên -> bé về góc dưới-phải quen thuộc. */
    try { initGuidePathFs(); } catch (eFsGuide) {
      if (window.console && console.warn) console.warn("Guide path-fs off:", eFsGuide);
    }
    function initGuidePathFs() {
      var fsStyle = document.createElement("style");
      fsStyle.id = "guide-fs-style";
      fsStyle.textContent =
        "body.ttc-path-fs-lock .guide-roam{z-index:2147483000 !important;width:88px}" +
        "body.ttc-path-fs-lock .guide-wrap{z-index:2147483001 !important}" +
        "body.ttc-path-fs-lock .guide-restore{z-index:2147483000 !important}" +
        "body.ttc-path-fs-lock .guide-spot-overlay{z-index:2147482999 !important}" +
        "body.ttc-path-fs-lock .guide-bubble{bottom:auto;top:calc(100% + 10px);border-radius:16px 4px 16px 16px}" +
        "body.ttc-path-fs-lock .guide-roam.guide-bubble-left .guide-bubble{border-radius:4px 16px 16px 16px}" +
        "@media (max-width:720px){body.ttc-path-fs-lock .guide-roam{width:74px}}";
      document.head.appendChild(fsStyle);
      var wasFs = false;
      setInterval(function () {
        var on = pathFsActive();
        if (on === wasFs) return;
        wasFs = on;
        if (roam.hidden || tripActive) return;
        if (on) {
          runTo(dockX("left"), dockY(), jumpOtter);
        } else {
          runTo(dockX("right"), dockY());
        }
      }, 700);
    }
    function initStudyBuddy() {
      var PROGRESS_KEY = "otter2_hsk_vocab_progress_v1";
      var STUDY_KEY = "otter2_guide_study_v1";
      var GOAL_DEFAULT = 10;
      var POLL_MS = Number(window.__OTTER2_STUDY_POLL_MS) > 0 ? Number(window.__OTTER2_STUDY_POLL_MS) : 5000;
      var GREET_MS = Number(window.__OTTER2_STUDY_GREET_MS) > 0 ? Number(window.__OTTER2_STUDY_GREET_MS) : 14000;
      var IDLE_MS = 120000;        /* ngồi yên 2 phút mới nhắc */
      var IDLE_GAP_MS = 600000;    /* hai lần nhắc cách nhau >= 10 phút */
      var IDLE_MAX = 3;            /* tối đa 3 lần nhắc / ngày */

      function pad2(n) { return (n < 10 ? "0" : "") + n; }
      function todayStr() { var d = new Date(); return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate()); }
      function dayDiff(fromStr, toStr) {
        var a = String(fromStr || "").split("-"), b = String(toStr || "").split("-");
        if (a.length !== 3 || b.length !== 3) return 0;
        return Math.round((Date.UTC(+b[0], +b[1] - 1, +b[2]) - Date.UTC(+a[0], +a[1] - 1, +a[2])) / 86400000);
      }
      function countTotal(map) {
        var n = 0;
        if (!map || typeof map !== "object") return 0;
        for (var k in map) {
          if (!Object.prototype.hasOwnProperty.call(map, k)) continue;
          var s = map[k];
          if (!s || typeof s !== "object") continue;
          if (Object.prototype.toString.call(s.learned) === "[object Array]") { n += s.learned.length; continue; }
          for ( var w in s) {
            if (!Object.prototype.hasOwnProperty.call(s, w)) continue;
            if (w === "detailIndex" || w === "updatedAt" || w === "learned") continue;
            if (s[w]) n++;
          }
        }
        return n;
      }
      function readProgressTotal() {
        try {
          var raw = localStorage.getItem(PROGRESS_KEY);
          return countTotal(raw ? JSON.parse(raw) : null);
        } catch (e) { return 0; }
      }
      function loadStudy() {
        try {
          var raw = localStorage.getItem(STUDY_KEY);
          var o = raw ? JSON.parse(raw) : null;
          return o && typeof o === "object" ? o : null;
        } catch (e) { return null; }
      }

      var nowToday = todayStr();
      var study = loadStudy();
      var firstEver = false, isNewDay = false, gapDays = 0;
      if (!study) {
        study = { date: nowToday, base: readProgressTotal(), goal: GOAL_DEFAULT, lastVisit: nowToday,
                  enabled: true, idleNudges: 0, cheered5: "", cheeredGoal: "", pathGoalMark: "" };
        firstEver = true; isNewDay = true;
      } else {
        if (study.date !== nowToday) {
          gapDays = study.lastVisit ? dayDiff(study.lastVisit, nowToday) : 0;
          study.date = nowToday;
          study.base = readProgressTotal();
          study.cheered5 = ""; study.cheeredGoal = ""; study.idleNudges = 0;
          isNewDay = true;
        }
        if (typeof study.enabled !== "boolean") study.enabled = true;
        if (!(Number(study.goal) > 0)) study.goal = GOAL_DEFAULT;
        if (typeof study.base !== "number") study.base = readProgressTotal();
        study.lastVisit = nowToday;
      }
      function saveStudy() {
        try { localStorage.setItem(STUDY_KEY, JSON.stringify(study)); } catch (e) {}
      }
      saveStudy();

      function learnedToday() { return Math.max(0, readProgressTotal() - (Number(study.base) || 0)); }
      function studyOn() { return study.enabled !== false && !roam.hidden; }

      /* ----- (f) Hàng điều khiển trong #guidePanel: bật/tắt + trạng thái ----- */
      var studyStyle = document.createElement("style");
      studyStyle.textContent =
        ".guide-study{display:flex;align-items:center;gap:9px;margin-top:12px;flex-wrap:wrap}" +
        ".guide-study-status{margin:0;font-size:.8rem;font-weight:700;color:#8a877e}";
      document.head.appendChild(studyStyle);
      var studyToggle = null, studyStatus = null;
      try {
        var foot = guidePanel.querySelector(".guide-foot");
        var studyBox = document.createElement("div");
        studyBox.className = "guide-study";
        studyBox.innerHTML =
          '<button type="button" class="guide-voice" id="guideStudyToggle" aria-pressed="true">' +
            "<span>⏰ Nhắc học: Bật</span></button>" +
          '<p class="guide-study-status" id="guideStudyStatus" aria-live="polite"></p>';
        if (foot && foot.parentNode) foot.parentNode.insertBefore(studyBox, foot);
        studyToggle = studyBox.querySelector("#guideStudyToggle");
        studyStatus = studyBox.querySelector("#guideStudyStatus");
        if (studyToggle) {
          studyToggle.addEventListener("click", function () {
            study.enabled = study.enabled === false ? true : false;
            saveStudy();
            refreshStudyRow();
          });
        }
      } catch (ePanel) { /* panel phụ lỗi thì bỏ qua, nhắc học vẫn chạy nền */ }
      function refreshStudyRow() {
        if (studyToggle) {
          studyToggle.setAttribute("aria-pressed", study.enabled !== false ? "true" : "false");
          var sp = studyToggle.querySelector("span");
          if (sp) sp.textContent = study.enabled !== false ? "⏰ Nhắc học: Bật" : "⏰ Nhắc học: Tắt";
        }
        if (studyStatus) {
          studyStatus.textContent = "🎯 Hôm nay: " + learnedToday() + "/" + study.goal + " từ";
        }
      }
      refreshStudyRow();
      try {
        var panelObs = new MutationObserver(function () { if (!guidePanel.hidden) refreshStudyRow(); });
        panelObs.observe(guidePanel, { attributes: true, attributeFilter: ["hidden"] });
      } catch (eObs) {}

      /* ----- (b) Chào theo ngữ cảnh: 1 lần/phiên, chỉ khi sang ngày mới ----- */
      if (isNewDay) {
        setTimeout(function () {
          if (!studyOn() || !guidePanel.hidden) return;
          var msg;
          if (firstEver) {
            msg = "Chào bạn! Mình là Bé Rái Cá. Từ hôm nay mình sẽ nhắc học và đếm từ đã học cho bạn nhé — hôm nay mình học " + study.goal + " từ nhé? Rái Cá đếm cho bạn!";
          } else if (gapDays >= 2) {
            msg = "Lâu rồi mới gặp bạn đó! Vắng mấy hôm chắc bạn bận lắm — hôm nay mình học lại " + study.goal + " từ cho nóng máy nhé, Rái Cá đếm cho bạn!";
          } else {
            msg = "Chào buổi học mới! Hôm nay mình học " + study.goal + " từ nhé? Rái Cá đếm cho bạn — đủ mục tiêu là mình ăn mừng liền!";
          }
          say(msg);
        }, GREET_MS);
      }

      /* ----- (c) Cổ vũ mốc mục tiêu ngày (kho từ vựng toàn trang) ----- */
      function checkDailyMilestones() {
        refreshStudyRow();
        if (!studyOn()) return;
        var lt = learnedToday();
        if (lt >= study.goal && study.cheeredGoal !== nowToday) {
          study.cheeredGoal = nowToday;
          if (lt >= 5) study.cheered5 = nowToday;
          saveStudy();
          jumpOtter();
          say("🎉 TUYỆT VỜI! Bạn đã đạt mục tiêu hôm nay: " + lt + "/" + study.goal + " từ! Rái Cá tự hào về bạn lắm đó!");
          return;
        }
        if (lt >= 5 && study.cheered5 !== nowToday) {
          study.cheered5 = nowToday;
          saveStudy();
          jumpOtter();
          say("Giỏi quá! Bạn đã học được " + lt + " từ hôm nay rồi — sắp tới mục tiêu " + study.goal + " từ rồi đó, cố thêm chút nữa nhé!");
        }
      }

      /* ----- (e) Vào trong LỘ TRÌNH: quan sát #otter2PathHost ----- */
      var pathHost = document.getElementById("otter2PathHost");
      var lastPathDone = null, lastPathGoal = 0, wrongStreak = 0, lastPraiseAt = 0, lastFbSig = "";
      function pathScopeEl() {
        /* Panel bị PORTAL ra document.body khi fullscreen — luôn tra theo
           phần tử thật, nếu không observer/truy vấn bám #otter2PathHost sẽ
           mù hoàn toàn trong phiên học (đúng lỗi chủ web báo: vào lộ trình
           không thấy bé đâu). */
        return document.getElementById("ttcPathPanel") || pathHost;
      }
      function parsePathMeta() {
        var scope = pathScopeEl();
        if (!scope) return null;
        var meta = scope.querySelector(".ttc-path-game-meta");
        var txt = meta ? meta.textContent : (scope.textContent || "");
        var m = /Hôm nay\s+(\d+)\s*\/\s*(\d+)\s*từ/.exec(txt || "");
        return m ? { done: Number(m[1]), goal: Number(m[2]) } : null;
      }
      function checkPathMilestones() {
        var p = parsePathMeta();
        if (!p) return;
        if (lastPathDone === null || p.done < lastPathDone) {
          lastPathDone = p.done; lastPathGoal = p.goal;
          return;
        }
        if (p.done === lastPathDone && p.goal === lastPathGoal) return;
        var prev = lastPathDone;
        lastPathDone = p.done; lastPathGoal = p.goal;
        if (!studyOn()) return;
        var marks = [10, 25, 50, 100];
        for (var i = 0; i < marks.length; i++) {
          if (prev < marks[i] && p.done >= marks[i]) {
            (function (mark, done) {
              setTimeout(function () {
                if (studyOn()) { jumpOtter(); say("🎉 Mốc " + mark + " từ trong lộ trình! Bạn đã học " + done + " từ hôm nay — giỏi lắm, đi tiếp nào!"); }
              }, 1600);
            })(marks[i], p.done);
            break;
          }
        }
        if (p.goal > 0 && prev < p.goal && p.done >= p.goal) {
          var markKey = nowToday + ":" + p.goal;
          if (study.pathGoalMark !== markKey) {
            study.pathGoalMark = markKey;
            saveStudy();
            setTimeout(function () {
              if (studyOn()) { jumpOtter(); say("🏆 HOÀN THÀNH MỤC TIÊU LỘ TRÌNH! Bạn đã học đủ " + p.goal + " từ hôm nay. Rái Cá nể bạn luôn đó!"); }
            }, 1200);
          }
        }
      }
      function onPathFeedback() {
        var scope = pathScopeEl();
        if (!scope) return;
        var panel = scope.querySelector(".ttc-path-feedback");
        if (!panel) return;
        var isOk = panel.classList.contains("ttc-path-feedback-ok");
        var isBad = panel.classList.contains("ttc-path-feedback-bad");
        if (!isOk && !isBad) return;
        var sig = (isOk ? "ok|" : "bad|") + (panel.textContent || "").replace(/\s+/g, " ").slice(0, 90);
        if (sig === lastFbSig) return;
        lastFbSig = sig;
        if (isOk) {
          wrongStreak = 0;
          if (!studyOn()) return;
          var now = Date.now();
          if (now - lastPraiseAt < 120000) return;         /* tối đa 1 lần khen / 2 phút */
          if (Math.random() > 1 / 3) return;               /* chỉ thỉnh thoảng ~1/3 */
          lastPraiseAt = now;
          var lines = ["Chính xác! Giỏi quá!", "Đúng rồi đó! Bạn nhớ bài tốt lắm!", "Chuẩn luôn! Cứ thế phát huy nhé bạn!"];
          var line = lines[Math.floor(Math.random() * lines.length)];
          /* Trễ 1,6s để không cắt ngang giọng đọc mẫu chữ Hán của lộ trình */
          setTimeout(function () { if (studyOn()) say(line); }, 1600);
        } else {
          wrongStreak++;
          if (wrongStreak >= 3) {
            wrongStreak = 0;
            if (studyOn()) say("Sai cũng không sao đâu bạn — mình xem lại nghĩa của từ này nhé, lần sau chắc chắn sẽ nhớ!");
          }
        }
      }
      if (document.body && "MutationObserver" in window) {
        var fbTimer = null;
        var fbObs = new MutationObserver(function () {
          clearTimeout(fbTimer);
          fbTimer = setTimeout(function () {
            try { onPathFeedback(); } catch (eFb) {}
            try { checkPathMilestones(); } catch (ePm) {}
          }, 250);
        });
        fbObs.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ["class"] });
      }

      /* ----- (d) Nhắc nhẹ khi ngồi yên ----- */
      var lastActivity = Date.now(), lastInteractEl = null, lastNudgeAt = 0;
      function bumpActivity(ev) {
        lastActivity = Date.now();
        if (ev && ev.target) lastInteractEl = ev.target;
      }
      document.addEventListener("pointerdown", bumpActivity, true);
      document.addEventListener("keydown", bumpActivity, true);
      window.addEventListener("scroll", function () { lastActivity = Date.now(); }, { passive: true });
      setInterval(function () {
        if (!studyOn() || !guidePanel.hidden || tripActive || document.hidden) return;
        var now = Date.now();
        if (now < parkUntil) return;                        /* đang bị park vì người học thao tác */
        if ((Number(study.idleNudges) || 0) >= IDLE_MAX) return;
        if (now - lastActivity < IDLE_MS) return;
        if (lastNudgeAt && now - lastNudgeAt < IDLE_GAP_MS) return;
        var lt = learnedToday();
        if (lt >= study.goal) return;                       /* đã đủ mục tiêu thì không nhắc nữa */
        try {
          if (lastInteractEl && lastInteractEl.closest && lastInteractEl.closest(LEARN_SEL)) return;
        } catch (eLearn) {}
        study.idleNudges = (Number(study.idleNudges) || 0) + 1;
        saveStudy();
        lastNudgeAt = now;
        lastActivity = now;
        if (lt <= 0) {
          say("Bạn ơi, hôm nay mình chưa học từ nào nè — học vài từ cho đủ mục tiêu " + study.goal + " từ nhé? Bấm vào mình, mình dẫn đi liền!");
        } else {
          say("Nghỉ một chút rồi học tiếp nhé bạn! Còn " + (study.goal - lt) + " từ nữa là đủ mục tiêu hôm nay đó — Rái Cá chờ bạn nè.");
        }
      }, 15000);

      /* ----- Vòng poll chính: mốc ngày + mốc lộ trình + storage liên tab ----- */
      setInterval(function () {
        try { checkDailyMilestones(); } catch (eDm) {}
        try { checkPathMilestones(); } catch (ePm2) {}
      }, POLL_MS);
      window.addEventListener("storage", function (ev) {
        if (ev && ev.key === PROGRESS_KEY) {
          setTimeout(function () { try { checkDailyMilestones(); } catch (eSt) {} }, 300);
        }
      });
    }
  }
})();
